9	// This file contains the declaration of the Type class.  For more "Type"
10	// stuff, look in DerivedTypes.h.
11	//
12	//===----------------------------------------------------------------------===//
13	
14	#ifndef LLVM_IR_TYPE_H
15	#define LLVM_IR_TYPE_H
16	
17	#include "llvm/ADT/ArrayRef.h"
18	#include "llvm/Support/CBindingWrapping.h"
19	#include "llvm/Support/Casting.h"
20	#include "llvm/Support/Compiler.h"
21	#include "llvm/Support/ErrorHandling.h"
22	#include "llvm/Support/TypeSize.h"
23	#include <cassert>
24	#include <cstdint>
25	#include <iterator>
26	
27	namespace llvm {
28	
29	class ByteType;
30	class IntegerType;
31	struct fltSemantics;
32	class LLVMContext;
33	class PointerType;
34	class raw_ostream;
35	class StringRef;
36	template <typename PtrType> class SmallPtrSetImpl;
37	
38	/// The instances of the Type class are immutable: once they are created,
39	/// they are never changed.  Also note that only one instance of a particular
40	/// type is ever created.  Thus seeing if two types are equal is a matter of
41	/// doing a trivial pointer comparison. To enforce that no two equal instances
42	/// are created, Type instances can only be created via static factory methods
43	/// in class Type and in derived classes.  Once allocated, Types are never
44	/// free'd.
45	///
46	class Type {
47	public:
48	  //===--------------------------------------------------------------------===//
49	  /// Definitions of all of the base types for the Type system.  Based on this
50	  /// value, you can cast to a class defined in DerivedTypes.h.
51	  /// Note: If you add an element to this, you need to add an element to the
52	  /// Type::getPrimitiveType function, or else things will break!
53	  /// Also update LLVMTypeKind and LLVMGetTypeKind () in the C binding.
54	  ///
55	  enum TypeID {
56	    // PrimitiveTypes
57	    HalfTyID = 0,  ///< 16-bit floating point type
58	    BFloatTyID,    ///< 16-bit floating point type (7-bit significand)
59	    FloatTyID,     ///< 32-bit floating point type
60	    DoubleTyID,    ///< 64-bit floating point type
61	    X86_FP80TyID,  ///< 80-bit floating point type (X87)
62	    FP128TyID,     ///< 128-bit floating point type (112-bit significand)
63	    PPC_FP128TyID, ///< 128-bit floating point type (two 64-bits, PowerPC)
64	    VoidTyID,      ///< type with no size
65	    LabelTyID,     ///< Labels
66	    MetadataTyID,  ///< Metadata
67	    X86_AMXTyID,   ///< AMX vectors (8192 bits, X86 specific)
68	    TokenTyID,     ///< Tokens
69	
70	    // Derived types... see DerivedTypes.h file.
71	    IntegerTyID,        ///< Arbitrary bit width integers
72	    ByteTyID,           ///< Arbitrary bit width bytes
73	    FunctionTyID,       ///< Functions
74	    PointerTyID,        ///< Pointers
75	    StructTyID,         ///< Structures
76	    ArrayTyID,          ///< Arrays
77	    FixedVectorTyID,    ///< Fixed width SIMD vector type
78	    ScalableVectorTyID, ///< Scalable SIMD vector type
79	    TypedPointerTyID,   ///< Typed pointer used by some GPU targets
80	    TargetExtTyID,      ///< Target extension type
81	  };
82	
83	private:
84	  /// This refers to the LLVMContext in which this type was uniqued.
85	  LLVMContext &Context;
86	
87	  TypeID   ID : 8;            // The current base type of this type.
88	  unsigned SubclassData : 24; // Space for subclasses to store data.
89	                              // Note that this should be synchronized with
90	                              // MAX_INT_BITS value in IntegerType class.
91	
92	protected:
93	  friend class LLVMContextImpl;
94	
95	  explicit Type(LLVMContext &C, TypeID tid)
96	    : Context(C), ID(tid), SubclassData(0) {}
97	  ~Type() = default;
98	
99	  unsigned getSubclassData() const { return SubclassData; }
100	
101	  void setSubclassData(unsigned val) {
102	    SubclassData = val;
103	    // Ensure we don't have any accidental truncation.
104	    assert(getSubclassData() == val && "Subclass data too large for field");
105	  }
106	
107	  /// Keeps track of how many Type*'s there are in the ContainedTys list.
108	  unsigned NumContainedTys = 0;
109	
110	  /// A pointer to the array of Types contained by this Type. For example, this
111	  /// includes the arguments of a function type, the elements of a structure,
112	  /// the pointee of a pointer, the element type of an array, etc. This pointer
113	  /// may be 0 for types that don't contain other types (Integer, Double,
114	  /// Float).
115	  Type * const *ContainedTys = nullptr;
116	
117	public:
118	  /// Print the current type.
119	  /// Omit the type details if \p NoDetails == true.
120	  /// E.g., let %st = type { i32, i16 }
121	  /// When \p NoDetails is true, we only print %st.
122	  /// Put differently, \p NoDetails prints the type as if
123	  /// inlined with the operands when printing an instruction.
124	  LLVM_ABI void print(raw_ostream &O, bool IsForDebug = false,
125	                      bool NoDetails = false) const;
126	
127	  LLVM_ABI void dump() const;
128	
129	  /// Return the LLVMContext in which this type was uniqued.
130	  LLVMContext &getContext() const { return Context; }
131	
132	  //===--------------------------------------------------------------------===//
133	  // Accessors for working with types.
134	  //
135	
136	  /// Return the type id for the type. This will return one of the TypeID enum
137	  /// elements defined above.
138	  TypeID getTypeID() const { return ID; }
139	
140	  /// Return true if this is 'void'.
141	  bool isVoidTy() const { return getTypeID() == VoidTyID; }
142	
143	  /// Return true if this is 'half', a 16-bit IEEE fp type.
144	  bool isHalfTy() const { return getTypeID() == HalfTyID; }
145	
146	  /// Return true if this is 'bfloat', a 16-bit bfloat type.
147	  bool isBFloatTy() const { return getTypeID() == BFloatTyID; }
148	
149	  /// Return true if this is a 16-bit float type.
150	  bool is16bitFPTy() const {
151	    return getTypeID() == BFloatTyID || getTypeID() == HalfTyID;
152	  }
153	
154	  /// Return true if this is 'float', a 32-bit IEEE fp type.
155	  bool isFloatTy() const { return getTypeID() == FloatTyID; }
156	
157	  /// Return true if this is 'double', a 64-bit IEEE fp type.
158	  bool isDoubleTy() const { return getTypeID() == DoubleTyID; }
159	
160	  /// Return true if this is x86 long double.
161	  bool isX86_FP80Ty() const { return getTypeID() == X86_FP80TyID; }
162	
163	  /// Return true if this is 'fp128'.
164	  bool isFP128Ty() const { return getTypeID() == FP128TyID; }
165	
166	  /// Return true if this is powerpc long double.
167	  bool isPPC_FP128Ty() const { return getTypeID() == PPC_FP128TyID; }
168	
169	  /// Return true if this is a well-behaved IEEE-like type, which has a IEEE
170	  /// compatible layout, and does not have non-IEEE values, such as x86_fp80's
171	  /// unnormal values.
172	  bool isIEEELikeFPTy() const {
173	    switch (getTypeID()) {
174	    case DoubleTyID:
175	    case FloatTyID:
176	    case HalfTyID:
177	    case BFloatTyID:
178	    case FP128TyID:
179	      return true;
180	    default:
181	      return false;
182	    }
183	  }
184	
185	  /// Return true if this is one of the floating-point types
186	  bool isFloatingPointTy() const {
187	    return isIEEELikeFPTy() || getTypeID() == X86_FP80TyID ||
188	           getTypeID() == PPC_FP128TyID;
189	  }
190	
191	  /// Returns true if this is a floating-point type that is an unevaluated sum
192	  /// of multiple floating-point units.
193	  /// An example of such a type is ppc_fp128, also known as double-double, which
194	  /// consists of two IEEE 754 doubles.
195	  bool isMultiUnitFPType() const {
196	    return getTypeID() == PPC_FP128TyID;
197	  }
198	
199	  LLVM_ABI const fltSemantics &getFltSemantics() const;
200	
201	  /// Return true if this is X86 AMX.
202	  bool isX86_AMXTy() const { return getTypeID() == X86_AMXTyID; }
203	
204	  /// Return true if this is a target extension type.
205	  bool isTargetExtTy() const { return getTypeID() == TargetExtTyID; }
206	
207	  /// Return true if this is a target extension type with a scalable layout.
208	  LLVM_ABI bool isScalableTargetExtTy() const;
209	
210	  /// Return true if this is a type whose size is a known multiple of vscale.
211	  LLVM_ABI bool isScalableTy(SmallPtrSetImpl<const Type *> &Visited) const;
212	  LLVM_ABI bool isScalableTy() const;
213	
214	  /// Return true if this type is or contains a target extension type that
215	  /// disallows being used as a global.
216	  LLVM_ABI bool
217	  containsNonGlobalTargetExtType(SmallPtrSetImpl<const Type *> &Visited) const;
218	  LLVM_ABI bool containsNonGlobalTargetExtType() const;
219	
220	  /// Return true if this type is or contains a target extension type that
221	  /// disallows being used as a local.
222	  LLVM_ABI bool
223	  containsNonLocalTargetExtType(SmallPtrSetImpl<const Type *> &Visited) const;
224	  LLVM_ABI bool containsNonLocalTargetExtType() const;
225	
226	  /// Return true if this is a FP type or a vector of FP.
227	  bool isFPOrFPVectorTy() const { return getScalarType()->isFloatingPointTy(); }
228	
229	  /// Return true if this is 'label'.
230	  bool isLabelTy() const { return getTypeID() == LabelTyID; }
231	
232	  /// Return true if this is 'metadata'.
233	  bool isMetadataTy() const { return getTypeID() == MetadataTyID; }
234	
235	  /// Return true if this is 'token'.
236	  bool isTokenTy() const { return getTypeID() == TokenTyID; }
237	
238	  /// Returns true if this is 'token' or a token-like target type.s
239	  LLVM_ABI bool isTokenLikeTy() const;
240	
241	  /// True if this is an instance of ByteType.
242	  bool isByteTy() const { return getTypeID() == ByteTyID; }
243	
244	  /// Return true if this is a ByteType of the given width.
245	  LLVM_ABI bool isByteTy(unsigned BitWidth) const;
246	
247	  /// Return true if this is a byte type or a vector of byte types.
248	  bool isByteOrByteVectorTy() const { return getScalarType()->isByteTy(); }
249	
250	  /// Return true if this is a byte type or a vector of byte types of
251	  /// the given width.
252	  bool isByteOrByteVectorTy(unsigned BitWidth) const {
253	    return getScalarType()->isByteTy(BitWidth);
254	  }
255	
256	  /// True if this is an instance of IntegerType.
257	  bool isIntegerTy() const { return getTypeID() == IntegerTyID; }
258	
259	  /// Return true if this is an IntegerType of the given width.
260	  LLVM_ABI inline bool isIntegerTy(unsigned BitWidth) const;
261	
262	  /// Return true if this is an integer type or a vector of integer types.
263	  bool isIntOrIntVectorTy() const { return getScalarType()->isIntegerTy(); }
264	
265	  /// Return true if this is an integer type or a vector of integer types of
266	  /// the given width.
267	  LLVM_ABI inline bool isIntOrIntVectorTy(unsigned BitWidth) const;
268	
269	  /// Return true if this is an integer type or a pointer type.
270	  bool isIntOrPtrTy() const { return isIntegerTy() || isPointerTy(); }
271	
272	  /// True if this is an instance of FunctionType.
273	  bool isFunctionTy() const { return getTypeID() == FunctionTyID; }
274	
275	  /// True if this is an instance of StructType.
276	  bool isStructTy() const { return getTypeID() == StructTyID; }
277	
278	  /// True if this is an instance of ArrayType.
279	  bool isArrayTy() const { return getTypeID() == ArrayTyID; }
280	
281	  /// True if this is an instance of PointerType.
282	  bool isPointerTy() const { return getTypeID() == PointerTyID; }
283	
284	  /// Return true if this is a pointer type or a vector of pointer types.
285	  bool isPtrOrPtrVectorTy() const { return getScalarType()->isPointerTy(); }
286	
287	  /// True if this is an instance of VectorType.
288	  inline bool isVectorTy() const {
289	    return getTypeID() == ScalableVectorTyID || getTypeID() == FixedVectorTyID;
290	  }
291	
292	  // True if this is an instance of TargetExtType of RISC-V vector tuple.
293	  LLVM_ABI bool isRISCVVectorTupleTy() const;
294	
295	  /// Return true if this type could be converted with a lossless BitCast to
296	  /// type 'Ty'. For example, i8* to i32*. BitCasts are valid for types of the
297	  /// same size only where no re-interpretation of the bits is done.
298	  /// Determine if this type could be losslessly bitcast to Ty
299	  LLVM_ABI bool canLosslesslyBitCastTo(Type *Ty) const;
300	
301	  /// Return true if this type is empty, that is, it has no elements or all of
302	  /// its elements are empty.
303	  LLVM_ABI bool isEmptyTy() const;
304	
305	  /// Return true if the type is "first class", meaning it is a valid type for a
306	  /// Value.
307	  LLVM_ABI bool isFirstClassType() const;
308	
309	  /// Return true if the type is a valid type for a register in codegen. This
310	  /// includes all first-class types except struct and array types.
311	  bool isSingleValueType() const {
312	    return isFloatingPointTy() || isIntegerTy() || isPointerTy() ||
313	           isVectorTy() || isX86_AMXTy() || isTargetExtTy() || isByteTy();
314	  }
315	
316	  /// Return true if the type is an aggregate type. This means it is valid as
317	  /// the first operand of an insertvalue or extractvalue instruction. This
318	  /// includes struct and array types, but does not include vector types.
319	  bool isAggregateType() const {
320	    return getTypeID() == StructTyID || getTypeID() == ArrayTyID;
321	  }
322	
323	  /// Return true if it makes sense to take the size of this type. To get the
324	  /// actual size for a particular target, it is reasonable to use the
325	  /// DataLayout subsystem to do this.
326	  bool isSized(SmallPtrSetImpl<Type*> *Visited = nullptr) const {
327	    // If it's a primitive, it is always sized.
328	    if (getTypeID() == IntegerTyID || isFloatingPointTy() ||
329	        getTypeID() == PointerTyID || getTypeID() == X86_AMXTyID ||
330	        getTypeID() == ByteTyID)
331	      return true;
332	    // If it is not something that can have a size (e.g. a function or label),
333	    // it doesn't have a size.
334	    if (getTypeID() != StructTyID && getTypeID() != ArrayTyID &&
335	        !isVectorTy() && getTypeID() != TargetExtTyID)
336	      return false;
337	    // Otherwise we have to try harder to decide.
338	    return isSizedDerivedType(Visited);
339	  }
340	
341	  /// Return the basic size of this type if it is a primitive type. These are
342	  /// fixed by LLVM and are not target-dependent.
343	  /// This will return zero if the type does not have a size or is not a
344	  /// primitive type.
345	  ///
346	  /// If this is a scalable vector type, the scalable property will be set and
347	  /// the runtime size will be a positive integer multiple of the base size.
348	  ///
349	  /// Note that this may not reflect the size of memory allocated for an
350	  /// instance of the type or the number of bytes that are written when an
351	  /// instance of the type is stored to memory. The DataLayout class provides
352	  /// additional query functions to provide this information.
353	  ///
354	  LLVM_ABI TypeSize getPrimitiveSizeInBits() const LLVM_READONLY;
355	
356	  /// If this is a vector type, return the getPrimitiveSizeInBits value for the
357	  /// element type. Otherwise return the getPrimitiveSizeInBits value for this
358	  /// type.
359	  LLVM_ABI unsigned getScalarSizeInBits() const LLVM_READONLY;
360	
361	  /// Return the width of the mantissa of this type. This is only valid on
362	  /// floating-point types. If the FP type does not have a stable mantissa (e.g.
363	  /// ppc long double), this method returns -1.
364	  LLVM_ABI int getFPMantissaWidth() const;
365	
366	  /// If this is a vector type, return the element type, otherwise return
367	  /// 'this'.
368	  inline Type *getScalarType() const {
369	    if (isVectorTy())
370	      return getContainedType(0);
371	    return const_cast<Type *>(this);
372	  }
373	
374	  //===--------------------------------------------------------------------===//
375	  // Type Iteration support.
376	  //
377	  using subtype_iterator = Type * const *;
378	
379	  subtype_iterator subtype_begin() const { return ContainedTys; }
380	  subtype_iterator subtype_end() const { return &ContainedTys[NumContainedTys];}
381	  ArrayRef<Type*> subtypes() const {
382	    return ArrayRef(subtype_begin(), subtype_end());
383	  }
384	
385	  using subtype_reverse_iterator = std::reverse_iterator<subtype_iterator>;
386	
387	  subtype_reverse_iterator subtype_rbegin() const {
388	    return subtype_reverse_iterator(subtype_end());
389	  }
390	  subtype_reverse_iterator subtype_rend() const {
391	    return subtype_reverse_iterator(subtype_begin());
392	  }
393	
394	  /// This method is used to implement the type iterator (defined at the end of
395	  /// the file). For derived types, this returns the types 'contained' in the
396	  /// derived type.
397	  Type *getContainedType(unsigned i) const {
398	    assert(i < NumContainedTys && "Index out of range!");
399	    return ContainedTys[i];
400	  }
401	
402	  /// Return the number of types in the derived type.
403	  unsigned getNumContainedTypes() const { return NumContainedTys; }
404	
405	  //===--------------------------------------------------------------------===//
406	  // Helper methods corresponding to subclass methods.  This forces a cast to
407	  // the specified subclass and calls its accessor.  "getArrayNumElements" (for
408	  // example) is shorthand for cast<ArrayType>(Ty)->getNumElements().  This is
409	  // only intended to cover the core methods that are frequently used, helper
410	  // methods should not be added here.
411	
412	  LLVM_ABI inline unsigned getIntegerBitWidth() const;
413	  LLVM_ABI inline unsigned getByteBitWidth() const;
414	
415	  LLVM_ABI inline Type *getFunctionParamType(unsigned i) const;
416	  LLVM_ABI inline unsigned getFunctionNumParams() const;
417	  LLVM_ABI inline bool isFunctionVarArg() const;
418	
419	  LLVM_ABI inline StringRef getStructName() const;
420	  LLVM_ABI inline unsigned getStructNumElements() const;
421	  LLVM_ABI inline Type *getStructElementType(unsigned N) const;
422	
423	  LLVM_ABI inline uint64_t getArrayNumElements() const;
424	
425	  Type *getArrayElementType() const {
426	    assert(getTypeID() == ArrayTyID);
427	    return ContainedTys[0];
428	  }
429	
430	  LLVM_ABI inline StringRef getTargetExtName() const;
431	
432	  /// Given vector type, change the element type,
433	  /// whilst keeping the old number of elements.
434	  /// For non-vectors simply returns \p EltTy.
435	  LLVM_ABI inline Type *getWithNewType(Type *EltTy) const;
436	
437	  /// Given an integer or vector type, change the lane bitwidth to NewBitwidth,
438	  /// whilst keeping the old number of lanes.
439	  LLVM_ABI inline Type *getWithNewBitWidth(unsigned NewBitWidth) const;
440	
441	  /// Given scalar/vector integer type, returns a type with elements twice as
442	  /// wide as in the original type. For vectors, preserves element count.
443	  LLVM_ABI inline Type *getExtendedType() const;
444	
445	  /// Given scalar/vector integer type, returns a type with elements half as
446	  /// wide as in the original type. For vectors, preserves element count.
447	  LLVM_ABI inline Type *getTruncatedType() const;
448	
449	  /// Get the address space of this pointer or pointer vector type.
450	  LLVM_ABI inline unsigned getPointerAddressSpace() const;
451	
452	  //===--------------------------------------------------------------------===//
453	  // Static members exported by the Type class itself.  Useful for getting
454	  // instances of Type.
455	  //
456	
457	  /// Return a type based on an identifier.
458	  LLVM_ABI static Type *getPrimitiveType(LLVMContext &C, TypeID IDNumber);
459	
460	  //===--------------------------------------------------------------------===//
461	  // These are the builtin types that are always available.
462	  //
463	  LLVM_ABI static Type *getVoidTy(LLVMContext &C);
464	  LLVM_ABI static Type *getLabelTy(LLVMContext &C);
465	  LLVM_ABI static Type *getHalfTy(LLVMContext &C);
466	  LLVM_ABI static Type *getBFloatTy(LLVMContext &C);
467	  LLVM_ABI static Type *getFloatTy(LLVMContext &C);
468	  LLVM_ABI static Type *getDoubleTy(LLVMContext &C);
469	  LLVM_ABI static Type *getMetadataTy(LLVMContext &C);
470	  LLVM_ABI static Type *getX86_FP80Ty(LLVMContext &C);
471	  LLVM_ABI static Type *getFP128Ty(LLVMContext &C);
472	  LLVM_ABI static Type *getPPC_FP128Ty(LLVMContext &C);
473	  LLVM_ABI static Type *getX86_AMXTy(LLVMContext &C);
474	  LLVM_ABI static Type *getTokenTy(LLVMContext &C);
475	  LLVM_ABI static ByteType *getByteNTy(LLVMContext &C, unsigned N);
476	  LLVM_ABI static ByteType *getByte1Ty(LLVMContext &C);
477	  LLVM_ABI static ByteType *getByte8Ty(LLVMContext &C);
478	  LLVM_ABI static ByteType *getByte16Ty(LLVMContext &C);
479	  LLVM_ABI static ByteType *getByte32Ty(LLVMContext &C);
480	  LLVM_ABI static ByteType *getByte64Ty(LLVMContext &C);
481	  LLVM_ABI static ByteType *getByte128Ty(LLVMContext &C);
482	  LLVM_ABI static IntegerType *getIntNTy(LLVMContext &C, unsigned N);
483	  LLVM_ABI static IntegerType *getInt1Ty(LLVMContext &C);
484	  LLVM_ABI static IntegerType *getInt8Ty(LLVMContext &C);
485	  LLVM_ABI static IntegerType *getInt16Ty(LLVMContext &C);
486	  LLVM_ABI static IntegerType *getInt32Ty(LLVMContext &C);
487	  LLVM_ABI static IntegerType *getInt64Ty(LLVMContext &C);
488	  LLVM_ABI static IntegerType *getInt128Ty(LLVMContext &C);
489	  template <typename ScalarTy> static Type *getScalarTy(LLVMContext &C) {
490	    int noOfBits = sizeof(ScalarTy) * CHAR_BIT;
491	    if (std::is_integral<ScalarTy>::value) {
492	      return (Type*) Type::getIntNTy(C, noOfBits);
493	    } else if (std::is_floating_point<ScalarTy>::value) {
494	      switch (noOfBits) {
495	      case 32:
496	        return Type::getFloatTy(C);
497	      case 64:
498	        return Type::getDoubleTy(C);
499	      }
500	    }
501	    llvm_unreachable("Unsupported type in Type::getScalarTy");
502	  }
503	  LLVM_ABI static Type *getFloatingPointTy(LLVMContext &C,
504	                                           const fltSemantics &S);
505	
506	  //===--------------------------------------------------------------------===//
507	  // Convenience methods for getting byte/integer types.
508	  //
509	  /// Returns an integer (vector of integer) type with the same size of a byte
510	  /// of the given byte (vector of byte) type.
511	  LLVM_ABI static Type *getIntFromByteType(Type *);
512	
513	  /// Returns a byte (vector of byte) type with the same size of an integer of
514	  /// the given integer (vector of integer) type.
515	  LLVM_ABI static Type *getByteFromIntType(Type *);
516	
517	  //===--------------------------------------------------------------------===//
518	  // Convenience methods for getting pointer types.
519	  //
520	  LLVM_ABI static Type *getWasm_ExternrefTy(LLVMContext &C);
521	  LLVM_ABI static Type *getWasm_FuncrefTy(LLVMContext &C);
522	
523	private:
524	  /// Derived types like structures and arrays are sized iff all of the members
525	  /// of the type are sized as well. Since asking for their size is relatively
526	  /// uncommon, move this operation out-of-line.
527	  LLVM_ABI bool
528	  isSizedDerivedType(SmallPtrSetImpl<Type *> *Visited = nullptr) const;
529	};
530	
531	// Printing of types.
532	inline raw_ostream &operator<<(raw_ostream &OS, const Type &T) {
533	  T.print(OS);
534	  return OS;
535	}
536	
537	// allow isa<PointerType>(x) to work without DerivedTypes.h included.
538	template <> struct isa_impl<PointerType, Type> {
539	  static inline bool doit(const Type &Ty) {
540	    return Ty.getTypeID() == Type::PointerTyID;
541	  }
542	};
543	
544	// Create wrappers for C Binding types (see CBindingWrapping.h).
545	DEFINE_ISA_CONVERSION_FUNCTIONS(Type, LLVMTypeRef)
546	
547	/* Specialized opaque type conversions.
548	 */
549	inline Type **unwrap(LLVMTypeRef* Tys) {
550	  return reinterpret_cast<Type**>(Tys);
551	}
552	
553	inline LLVMTypeRef *wrap(Type **Tys) {
554	  return reinterpret_cast<LLVMTypeRef *>(Tys);
555	}
556	
557	} // end namespace llvm
