672	  /// Accumulate the constant offset this value has compared to a base pointer.
673	  /// Only 'getelementptr' instructions (GEPs) are accumulated but other
674	  /// instructions, e.g., casts, are stripped away as well.
675	  /// The accumulated constant offset is added to \p Offset and the base
676	  /// pointer is returned.
677	  ///
678	  /// The APInt \p Offset has to have a bit-width equal to the IntPtr type for
679	  /// the address space of 'this' pointer value, e.g., use
680	  /// DataLayout::getIndexTypeSizeInBits(Ty).
681	  ///
682	  /// If \p AllowNonInbounds is true, offsets in GEPs are stripped and
683	  /// accumulated even if the GEP is not "inbounds".
684	  ///
685	  /// If \p AllowInvariantGroup is true then this method also looks through
686	  /// strip.invariant.group and launder.invariant.group intrinsics.
687	  ///
688	  /// If \p ExternalAnalysis is provided it will be used to calculate a offset
689	  /// when a operand of GEP is not constant.
690	  /// For example, for a value \p ExternalAnalysis might try to calculate a
691	  /// lower bound. If \p ExternalAnalysis is successful, it should return true.
692	  ///
693	  /// If \p LookThroughIntToPtr is true then this method also looks through
694	  /// IntToPtr and PtrToInt constant expressions. The returned pointer may not
695	  /// have the same provenance as this value.
696	  ///
697	  /// If this is called on a non-pointer value, it returns 'this' and the
698	  /// \p Offset is not modified.
699	  ///
700	  /// Note that this function will never return a nullptr. It will also never
701	  /// manipulate the \p Offset in a way that would not match the difference
702	  /// between the underlying value and the returned one. Thus, if a variable
703	  /// offset is encountered during traversal, the returned value is the first
704	  /// traversed Value that introduces a non-constant offset and \p Offset is the
705	  /// accumulated constant offset up to that point.
706	  LLVM_ABI const Value *stripAndAccumulateConstantOffsets(
707	      const DataLayout &DL, APInt &Offset, bool AllowNonInbounds,
708	      bool AllowInvariantGroup = false,
709	      function_ref<bool(Value &Value, APInt &Offset)> ExternalAnalysis =
710	          nullptr,
711	      bool LookThroughIntToPtr = false) const;
712	
713	  Value *stripAndAccumulateConstantOffsets(
714	      const DataLayout &DL, APInt &Offset, bool AllowNonInbounds,
715	      bool AllowInvariantGroup = false,
716	      function_ref<bool(Value &Value, APInt &Offset)> ExternalAnalysis =
717	          nullptr,
718	      bool LookThroughIntToPtr = false) {
719	    return const_cast<Value *>(
720	        static_cast<const Value *>(this)->stripAndAccumulateConstantOffsets(
721	            DL, Offset, AllowNonInbounds, AllowInvariantGroup, ExternalAnalysis,
722	            LookThroughIntToPtr));
723	  }
724	
725	  /// This is a wrapper around stripAndAccumulateConstantOffsets with the
726	  /// in-bounds requirement set to false.
727	  const Value *stripAndAccumulateInBoundsConstantOffsets(const DataLayout &DL,
728	                                                         APInt &Offset) const {
729	    return stripAndAccumulateConstantOffsets(DL, Offset,
730	                                             /* AllowNonInbounds */ false);
731	  }
732	  Value *stripAndAccumulateInBoundsConstantOffsets(const DataLayout &DL,
733	                                                   APInt &Offset) {
734	    return stripAndAccumulateConstantOffsets(DL, Offset,
735	                                             /* AllowNonInbounds */ false);
736	  }
737	
738	  /// Strip off pointer casts and inbounds GEPs.
739	  ///
740	  /// Returns the original pointer value.  If this is called on a non-pointer
741	  /// value, it returns 'this'.
742	  LLVM_ABI const Value *stripInBoundsOffsets(
743	      function_ref<void(const Value *)> Func = [](const Value *) {}) const;
744	  inline Value *stripInBoundsOffsets(function_ref<void(const Value *)> Func =
745	                                  [](const Value *) {}) {
746	    return const_cast<Value *>(
747	        static_cast<const Value *>(this)->stripInBoundsOffsets(Func));
748	  }
749	
750	  /// If this ptr is provably equal to \p Other plus a constant offset, return
751	  /// that offset in bytes. Essentially `ptr this` subtract `ptr Other`.
752	  LLVM_ABI std::optional<int64_t>
753	  getPointerOffsetFrom(const Value *Other, const DataLayout &DL) const;
754	
755	  /// Return true if the memory object referred to by V can by freed in the
756	  /// scope for which the SSA value defining the allocation is statically
757	  /// defined.  E.g.  deallocation after the static scope of a value does not
758	  /// count, but a deallocation before that does.
759	  LLVM_ABI bool canBeFreed() const;
760	
761	  /// Returns the number of bytes known to be dereferenceable for the
762	  /// pointer value.
763	  ///
764	  /// If CanBeNull is set by this function the pointer can either be null or be
765	  /// dereferenceable up to the returned number of bytes.
766	  ///
767	  /// If CanBeFreed is non-null, it will be populated with information on
768	  /// whether the pointer might be freed, i.e. is only known dereferenceable
769	  /// at the point of definition. By passing null the caller indicates that it
770	  /// does not care.
771	  LLVM_ABI uint64_t getPointerDereferenceableBytes(const DataLayout &DL,
772	                                                   bool &CanBeNull,
773	                                                   bool *CanBeFreed) const;
774	
775	  /// Returns an alignment of the pointer value.
776	  ///
777	  /// Returns an alignment which is either specified explicitly, e.g. via
778	  /// align attribute of a function argument, or guaranteed by DataLayout.
779	  LLVM_ABI Align getPointerAlignment(const DataLayout &DL) const;
780	
781	  /// Translate PHI node to its predecessor from the given basic block.
782	  ///
783	  /// If this value is a PHI node with CurBB as its parent, return the value in
784	  /// the PHI node corresponding to PredBB.  If not, return ourself.  This is
785	  /// useful if you want to know the value something has in a predecessor
786	  /// block.
787	  LLVM_ABI const Value *DoPHITranslation(const BasicBlock *CurBB,
788	                                         const BasicBlock *PredBB) const;
789	  Value *DoPHITranslation(const BasicBlock *CurBB, const BasicBlock *PredBB) {
790	    return const_cast<Value *>(
791	             static_cast<const Value *>(this)->DoPHITranslation(CurBB, PredBB));
792	  }
793	
794	  /// The maximum alignment for instructions.
795	  ///
796	  /// This is the greatest alignment value supported by load, store, and alloca
797	  /// instructions, and global values.
798	  static constexpr unsigned MaxAlignmentExponent = 32;
799	  static constexpr uint64_t MaximumAlignment = 1ULL << MaxAlignmentExponent;
800	
801	  /// Mutate the type of this Value to be of the specified type.
802	  ///
803	  /// Note that this is an extremely dangerous operation which can create
804	  /// completely invalid IR very easily.  It is strongly recommended that you
805	  /// recreate IR objects with the right types instead of mutating them in
806	  /// place.
807	  void mutateType(Type *Ty) {
808	    VTy = Ty;
809	  }
810	
811	  /// Sort the use-list.
812	  ///
813	  /// Sorts the Value's use-list by Cmp using a stable mergesort.  Cmp is
814	  /// expected to compare two \a Use references.
815	  template <class Compare> void sortUseList(Compare Cmp);
816	
817	  /// Reverse the use-list.
818	  LLVM_ABI void reverseUseList();
819	
820	private:
821	  /// Merge two lists together.
822	  ///
823	  /// Merges \c L and \c R using \c Cmp.  To enable stable sorts, always pushes
824	  /// "equal" items from L before items from R.
825	  ///
826	  /// \return the first element in the list.
827	  ///
828	  /// \note Completely ignores \a Use::Prev (doesn't read, doesn't update).
829	  template <class Compare>
830	  static Use *mergeUseLists(Use *L, Use *R, Compare Cmp) {
831	    Use *Merged;
832	    Use **Next = &Merged;
833	
834	    while (true) {
835	      if (!L) {
836	        *Next = R;
837	        break;
838	      }
839	      if (!R) {
840	        *Next = L;
841	        break;
842	      }
843	      if (Cmp(*R, *L)) {
844	        *Next = R;
845	        Next = &R->Next;
846	        R = R->Next;
847	      } else {
848	        *Next = L;
849	        Next = &L->Next;
850	        L = L->Next;
851	      }
852	    }
853	
854	    return Merged;
855	  }
856	
857	protected:
858	  unsigned short getSubclassDataFromValue() const { return SubclassData; }
859	  void setValueSubclassData(unsigned short D) { SubclassData = D; }
860	};
861	
862	struct ValueDeleter { void operator()(Value *V) { V->deleteValue(); } };
863	
864	/// Use this instead of std::unique_ptr<Value> or std::unique_ptr<Instruction>.
865	/// Those don't work because Value and Instruction's destructors are protected,
866	/// aren't virtual, and won't destroy the complete object.
867	using unique_value = std::unique_ptr<Value, ValueDeleter>;
868	
869	inline raw_ostream &operator<<(raw_ostream &OS, const Value &V) {
870	  V.print(OS);
871	  return OS;
872	}
873	
874	void Use::set(Value *V) {
875	  removeFromList();
876	  Val = V;
877	  if (V)
878	    V->addUse(*this);
879	}
880	
881	Value *Use::operator=(Value *RHS) {
882	  set(RHS);
883	  return RHS;
884	}
885	
886	const Use &Use::operator=(const Use &RHS) {
887	  set(RHS.Val);
888	  return *this;
889	}
890	
891	template <class Compare> void Value::sortUseList(Compare Cmp) {
892	  if (!UseList || !UseList->Next)
893	    // No need to sort 0 or 1 uses.
894	    return;
895	
896	  // Note: this function completely ignores Prev pointers until the end when
897	  // they're fixed en masse.
898	
899	  // Create a binomial vector of sorted lists, visiting uses one at a time and
900	  // merging lists as necessary.
901	  const unsigned MaxSlots = 32;
902	  Use *Slots[MaxSlots];
903	
904	  // Collect the first use, turning it into a single-item list.
905	  Use *Next = UseList->Next;
906	  UseList->Next = nullptr;
907	  unsigned NumSlots = 1;
908	  Slots[0] = UseList;
909	
910	  // Collect all but the last use.
911	  while (Next->Next) {
912	    Use *Current = Next;
913	    Next = Current->Next;
914	
915	    // Turn Current into a single-item list.
916	    Current->Next = nullptr;
917	
918	    // Save Current in the first available slot, merging on collisions.
919	    unsigned I;
920	    for (I = 0; I < NumSlots; ++I) {
921	      if (!Slots[I])
922	        break;
923	
924	      // Merge two lists, doubling the size of Current and emptying slot I.
925	      //
926	      // Since the uses in Slots[I] originally preceded those in Current, send
927	      // Slots[I] in as the left parameter to maintain a stable sort.
928	      Current = mergeUseLists(Slots[I], Current, Cmp);
929	      Slots[I] = nullptr;
930	    }
931	    // Check if this is a new slot.
932	    if (I == NumSlots) {
933	      ++NumSlots;
934	      assert(NumSlots <= MaxSlots && "Use list bigger than 2^32");
935	    }
936	
937	    // Found an open slot.
938	    Slots[I] = Current;
939	  }
940	
941	  // Merge all the lists together.
942	  assert(Next && "Expected one more Use");
943	  assert(!Next->Next && "Expected only one Use");
944	  UseList = Next;
945	  for (unsigned I = 0; I < NumSlots; ++I)
946	    if (Slots[I])
947	      // Since the uses in Slots[I] originally preceded those in UseList, send
948	      // Slots[I] in as the left parameter to maintain a stable sort.
949	      UseList = mergeUseLists(Slots[I], UseList, Cmp);
950	
951	  // Fix the Prev pointers.
952	  for (Use *I = UseList, **Prev = &UseList; I; I = I->Next) {
953	    I->Prev = Prev;
954	    Prev = &I->Next;
955	  }
956	}
