958	// isa - Provide some specializations of isa so that we don't have to include
959	// the subtype header files to test to see if the value is a subclass...
960	//
961	template <> struct isa_impl<Constant, Value> {
962	  static inline bool doit(const Value &Val) {
963	    static_assert(Value::ConstantFirstVal == 0,
964	                  "Val.getValueID() >= Value::ConstantFirstVal");
