999	  }
1000	};
1001	
1002	template <> struct isa_impl<BasicBlock, Value> {
1003	  static inline bool doit(const Value &Val) {
1004	    return Val.getValueID() == Value::BasicBlockVal;
1005	  }
1006	};
1007	
1008	template <> struct isa_impl<Function, Value> {
1009	  static inline bool doit(const Value &Val) {
1010	    return Val.getValueID() == Value::FunctionVal;
1011	  }
1012	};
1013	
1014	template <> struct isa_impl<GlobalVariable, Value> {
1015	  static inline bool doit(const Value &Val) {
1016	    return Val.getValueID() == Value::GlobalVariableVal;
1017	  }
1018	};
1019	
1020	template <> struct isa_impl<GlobalAlias, Value> {
1021	  static inline bool doit(const Value &Val) {
1022	    return Val.getValueID() == Value::GlobalAliasVal;
1023	  }
1024	};
1025	
1026	template <> struct isa_impl<GlobalIFunc, Value> {
1027	  static inline bool doit(const Value &Val) {
1028	    return Val.getValueID() == Value::GlobalIFuncVal;
1029	  }
1030	};
1031	
1032	template <> struct isa_impl<GlobalValue, Value> {
1033	  static inline bool doit(const Value &Val) {
1034	    return isa<GlobalObject>(Val) || isa<GlobalAlias>(Val);
1035	  }
1036	};
1037	
1038	template <> struct isa_impl<GlobalObject, Value> {
1039	  static inline bool doit(const Value &Val) {
1040	    return isa<GlobalVariable>(Val) || isa<Function>(Val) ||
1041	           isa<GlobalIFunc>(Val);
1042	  }
1043	};
1044	
1045	// Create wrappers for C Binding types (see CBindingWrapping.h).
1046	DEFINE_ISA_CONVERSION_FUNCTIONS(Value, LLVMValueRef)
1047	
1048	// Specialized opaque value conversions.
1049	inline Value **unwrap(LLVMValueRef *Vals) {
1050	  return reinterpret_cast<Value**>(Vals);
