757	/// Class to represent pointers.
758	class PointerType : public Type {
759	  explicit PointerType(LLVMContext &C, unsigned AddrSpace);
760	
761	public:
762	  PointerType(const PointerType &) = delete;
763	  PointerType &operator=(const PointerType &) = delete;
764	
765	  /// This constructs an opaque pointer to an object in a numbered address
766	  /// space.
767	  LLVM_ABI static PointerType *get(LLVMContext &C, unsigned AddressSpace);
768	
769	  /// This constructs an opaque pointer to an object in the
770	  /// default address space (address space zero).
771	  static PointerType *getUnqual(LLVMContext &C) {
772	    return PointerType::get(C, 0);
773	  }
774	
775	  /// Return true if the specified type is valid as a element type.
776	  LLVM_ABI static bool isValidElementType(Type *ElemTy);
777	
778	  /// Return true if we can load or store from a pointer to this type.
779	  LLVM_ABI static bool isLoadableOrStorableType(Type *ElemTy);
780	
781	  /// Return the address space of the Pointer type.
782	  inline unsigned getAddressSpace() const { return getSubclassData(); }
783	
784	  /// Implement support type inquiry through isa, cast, and dyn_cast.
785	  static bool classof(const Type *T) {
786	    return T->getTypeID() == PointerTyID;
787	  }
788	};
789	
790	Type *Type::getExtendedType() const {
791	  assert(
792	      isIntOrIntVectorTy() &&
793	      "Original type expected to be a vector of integers or a scalar integer.");
794	  if (auto *VTy = dyn_cast<VectorType>(this))
795	    return VectorType::getExtendedElementVectorType(
796	        const_cast<VectorType *>(VTy));
797	  return cast<IntegerType>(this)->getExtendedType();
798	}
799	
800	Type *Type::getTruncatedType() const {
801	  assert(
802	      isIntOrIntVectorTy() &&
803	      "Original type expected to be a vector of integers or a scalar integer.");
804	  if (auto *VTy = dyn_cast<VectorType>(this))
805	    return VectorType::getTruncatedElementVectorType(
806	        const_cast<VectorType *>(VTy));
807	  return cast<IntegerType>(this)->getTruncatedType();
808	}
809	
810	Type *Type::getWithNewType(Type *EltTy) const {
811	  if (auto *VTy = dyn_cast<VectorType>(this))
812	    return VectorType::get(EltTy, VTy->getElementCount());
813	  return EltTy;
814	}
815	
816	Type *Type::getWithNewBitWidth(unsigned NewBitWidth) const {
817	  assert(
818	      isIntOrIntVectorTy() &&
819	      "Original type expected to be a vector of integers or a scalar integer.");
820	  return getWithNewType(getIntNTy(getContext(), NewBitWidth));
821	}
822	
823	unsigned Type::getPointerAddressSpace() const {
824	  return cast<PointerType>(getScalarType())->getAddressSpace();
825	}
826	
827	/// Class to represent target extensions types, which are generally
828	/// unintrospectable from target-independent optimizations.
829	///
830	/// Target extension types have a string name, and optionally have type and/or
831	/// integer parameters. The exact meaning of any parameters is dependent on the
832	/// target.
833	class TargetExtType : public Type {
834	  TargetExtType(LLVMContext &C, StringRef Name, ArrayRef<Type *> Types,
835	                ArrayRef<unsigned> Ints);
836	
837	  // These strings are ultimately owned by the context.
838	  StringRef Name;
839	  unsigned *IntParams;
840	
841	public:
842	  TargetExtType(const TargetExtType &) = delete;
843	  TargetExtType &operator=(const TargetExtType &) = delete;
844	
845	  /// Return a target extension type having the specified name and optional
846	  /// type and integer parameters.
847	  LLVM_ABI static TargetExtType *get(LLVMContext &Context, StringRef Name,
848	                                     ArrayRef<Type *> Types = {},
849	                                     ArrayRef<unsigned> Ints = {});
850	
851	  /// Return a target extension type having the specified name and optional
852	  /// type and integer parameters, or an appropriate Error if it fails the
853	  /// parameters check.
854	  LLVM_ABI static Expected<TargetExtType *>
855	  getOrError(LLVMContext &Context, StringRef Name, ArrayRef<Type *> Types = {},
856	             ArrayRef<unsigned> Ints = {});
857	
858	  /// Check that a newly created target extension type has the expected number
859	  /// of type parameters and integer parameters, returning the type itself if OK
860	  /// or an appropriate Error if not.
861	  LLVM_ABI static Expected<TargetExtType *> checkParams(TargetExtType *TTy);
862	
863	  /// Return the name for this target extension type. Two distinct target
864	  /// extension types may have the same name if their type or integer parameters
865	  /// differ.
866	  StringRef getName() const { return Name; }
867	
868	  /// Return the type parameters for this particular target extension type. If
869	  /// there are no parameters, an empty array is returned.
870	  ArrayRef<Type *> type_params() const {
871	    return ArrayRef(type_param_begin(), type_param_end());
872	  }
873	
874	  using type_param_iterator = Type::subtype_iterator;
875	  type_param_iterator type_param_begin() const { return ContainedTys; }
876	  type_param_iterator type_param_end() const {
877	    return &ContainedTys[NumContainedTys];
878	  }
879	
880	  Type *getTypeParameter(unsigned i) const { return getContainedType(i); }
881	  unsigned getNumTypeParameters() const { return getNumContainedTypes(); }
882	
883	  /// Return the integer parameters for this particular target extension type.
884	  /// If there are no parameters, an empty array is returned.
885	  ArrayRef<unsigned> int_params() const {
886	    return ArrayRef(IntParams, getNumIntParameters());
887	  }
888	
889	  unsigned getIntParameter(unsigned i) const { return IntParams[i]; }
890	  unsigned getNumIntParameters() const { return getSubclassData(); }
891	
892	  enum Property {
893	    /// zeroinitializer is valid for this target extension type.
894	    HasZeroInit = 1U << 0,
895	    /// This type may be used as the value type of a global variable.
896	    CanBeGlobal = 1U << 1,
897	    /// This type may be allocated on the stack, either as the allocated type
898	    /// of an alloca instruction or as a byval function parameter.
899	    CanBeLocal = 1U << 2,
900	    /// This type may be used as an element in a vector.
901	    CanBeVectorElement = 1U << 3,
902	    // This type can only be used in intrinsic arguments and return values.
903	    /// In particular, it cannot be used in select and phi instructions.
904	    IsTokenLike = 1U << 4,
905	  };
906	
907	  /// Returns true if the target extension type contains the given property.
908	  LLVM_ABI bool hasProperty(Property Prop) const;
909	
910	  /// Returns an underlying layout type for the target extension type. This
911	  /// type can be used to query size and alignment information, if it is
912	  /// appropriate (although note that the layout type may also be void). It is
913	  /// not legal to bitcast between this type and the layout type, however.
914	  LLVM_ABI Type *getLayoutType() const;
915	
916	  /// Methods for support type inquiry through isa, cast, and dyn_cast.
917	  static bool classof(const Type *T) { return T->getTypeID() == TargetExtTyID; }
918	};
919	
920	StringRef Type::getTargetExtName() const {
921	  return cast<TargetExtType>(this)->getName();
922	}
923	
924	} // end namespace llvm
925	
926	#endif // LLVM_IR_DERIVEDTYPES_H
