7	//===----------------------------------------------------------------------===//
8	//
9	// This class defines the interface that one who uses a Value must implement.
10	// Each instance of the Value class keeps track of what User's have handles
11	// to it.
12	//
13	//  * Instructions are the largest class of Users.
14	//  * Constants may be users of other constants (think arrays and stuff)
15	//
16	//===----------------------------------------------------------------------===//
17	
18	#ifndef LLVM_IR_USER_H
19	#define LLVM_IR_USER_H
20	
21	#include "llvm/ADT/iterator.h"
22	#include "llvm/ADT/iterator_range.h"
23	#include "llvm/IR/Use.h"
24	#include "llvm/IR/Value.h"
25	#include "llvm/Support/Casting.h"
26	#include "llvm/Support/Compiler.h"
27	#include "llvm/Support/ErrorHandling.h"
28	#include <cassert>
29	#include <cstddef>
30	#include <cstdint>
31	#include <iterator>
32	
33	namespace llvm {
34	
35	template <typename T> class ArrayRef;
36	template <typename T> class MutableArrayRef;
37	
38	/// Compile-time customization of User operands.
39	///
40	/// Customizes operand-related allocators and accessors.
41	template <class>
42	struct OperandTraits;
43	
44	class User : public Value {
45	  friend struct HungoffOperandTraits;
46	  template <class ConstantClass> friend struct ConstantAggrKeyType;
47	
48	  LLVM_ATTRIBUTE_ALWAYS_INLINE static void *
49	  allocateFixedOperandUser(size_t, unsigned, unsigned);
50	
51	protected:
52	  // Disable the default operator new, as all subclasses must use one of the
53	  // custom operators below depending on how they store their operands.
54	  void *operator new(size_t Size) = delete;
55	
56	  /// Indicates this User has operands "hung off" in another allocation.
57	  struct HungOffOperandsAllocMarker {};
58	
59	  /// Indicates this User has operands co-allocated.
60	  struct IntrusiveOperandsAllocMarker {
61	    /// The number of operands for this User.
62	    const unsigned NumOps;
63	  };
64	
65	  /// Indicates this User has operands and a descriptor co-allocated .
66	  struct IntrusiveOperandsAndDescriptorAllocMarker {
67	    /// The number of operands for this User.
68	    const unsigned NumOps;
69	    /// The number of bytes to allocate for the descriptor. Must be divisible by
70	    /// `sizeof(void *)`.
71	    const unsigned DescBytes;
72	  };
73	
74	  /// Information about how a User object was allocated, to be passed into the
75	  /// User constructor.
76	  ///
77	  /// DO NOT USE DIRECTLY. Use one of the `AllocMarker` structs instead, they
78	  /// call all be implicitly converted to `AllocInfo`.
79	  struct AllocInfo {
80	  public:
81	    const unsigned NumOps : NumUserOperandsBits;
82	    LLVM_PREFERRED_TYPE(bool)
83	    const unsigned HasHungOffUses : 1;
84	    LLVM_PREFERRED_TYPE(bool)
85	    const unsigned HasDescriptor : 1;
86	
87	    AllocInfo() = delete;
88	
89	    constexpr AllocInfo(const HungOffOperandsAllocMarker)
90	        : NumOps(0), HasHungOffUses(true), HasDescriptor(false) {}
91	
92	    constexpr AllocInfo(const IntrusiveOperandsAllocMarker Alloc)
93	        : NumOps(Alloc.NumOps), HasHungOffUses(false), HasDescriptor(false) {}
94	
95	    constexpr AllocInfo(const IntrusiveOperandsAndDescriptorAllocMarker Alloc)
96	        : NumOps(Alloc.NumOps), HasHungOffUses(false),
97	          HasDescriptor(Alloc.DescBytes != 0) {}
98	  };
99	
100	  /// Allocate a User with an operand pointer co-allocated.
101	  ///
102	  /// This is used for subclasses which need to allocate a variable number
103	  /// of operands, ie, 'hung off uses'.
104	  LLVM_ABI void *operator new(size_t Size, HungOffOperandsAllocMarker);
105	
106	  /// Allocate a User with the operands co-allocated.
107	  ///
108	  /// This is used for subclasses which have a fixed number of operands.
109	  LLVM_ABI void *operator new(size_t Size,
110	                              IntrusiveOperandsAllocMarker allocTrait);
111	
112	  /// Allocate a User with the operands co-allocated.  If DescBytes is non-zero
113	  /// then allocate an additional DescBytes bytes before the operands. These
114	  /// bytes can be accessed by calling getDescriptor.
115	  LLVM_ABI void *
116	  operator new(size_t Size,
117	               IntrusiveOperandsAndDescriptorAllocMarker allocTrait);
118	
119	  User(Type *ty, unsigned vty, AllocInfo AllocInfo) : Value(ty, vty) {
120	    assert(AllocInfo.NumOps < (1u << NumUserOperandsBits) &&
121	           "Too many operands");
122	    NumUserOperands = AllocInfo.NumOps;
123	    assert((!AllocInfo.HasDescriptor || !AllocInfo.HasHungOffUses) &&
124	           "Cannot have both hung off uses and a descriptor");
125	    HasHungOffUses = AllocInfo.HasHungOffUses;
126	    HasDescriptor = AllocInfo.HasDescriptor;
127	    // If we have hung off uses, then the operand list should initially be
128	    // null.
129	    assert((!AllocInfo.HasHungOffUses || !getOperandList()) &&
130	           "Error in initializing hung off uses for User");
131	
132	    Use *Operands = reinterpret_cast<Use *>(this) - NumUserOperands;
133	    for (unsigned I = 0; I < NumUserOperands; ++I)
134	      new (&Operands[I]) Use(this);
135	  }
136	
137	  /// Allocate the array of Uses, followed by a pointer
138	  /// (with bottom bit set) to the User.
139	  /// \param WithExtraValues identifies callers which need N Value* allocated
140	  /// along the N operands.
141	  LLVM_ABI void allocHungoffUses(unsigned N, bool WithExtraValues = false);
142	
143	  /// Grow the number of hung off uses.  Note that allocHungoffUses
144	  /// should be called if there are no uses.
145	  LLVM_ABI void growHungoffUses(unsigned N, bool WithExtraValues = false);
146	
147	protected:
148	  // Use deleteValue() to delete a generic User.
149	  LLVM_ABI ~User();
150	
151	public:
152	  User(const User &) = delete;
153	
154	  /// Free memory allocated for User and Use objects.
155	  LLVM_ABI void operator delete(void *Usr);
156	  /// Placement delete - required by std, called if the ctor throws.
157	  LLVM_ABI void operator delete(void *Usr, HungOffOperandsAllocMarker);
158	  /// Placement delete - required by std, called if the ctor throws.
159	  LLVM_ABI void operator delete(void *Usr,
160	                                IntrusiveOperandsAndDescriptorAllocMarker);
161	  /// Placement delete - required by std, called if the ctor throws.
162	  LLVM_ABI void operator delete(void *Usr, IntrusiveOperandsAllocMarker Marker);
163	
164	protected:
165	  template <int Idx, typename U> static Use &OpFrom(const U *that) {
166	    return Idx < 0
167	      ? OperandTraits<U>::op_end(const_cast<U*>(that))[Idx]
168	      : OperandTraits<U>::op_begin(const_cast<U*>(that))[Idx];
169	  }
170	
171	  template <int Idx> Use &Op() {
172	    return OpFrom<Idx>(this);
173	  }
174	  template <int Idx> const Use &Op() const {
175	    return OpFrom<Idx>(this);
176	  }
177	
178	private:
179	  const Use *getHungOffOperands() const {
180	    return *(reinterpret_cast<const Use *const *>(this) - 1);
181	  }
182	
183	  Use *&getHungOffOperands() { return *(reinterpret_cast<Use **>(this) - 1); }
184	
185	  const Use *getIntrusiveOperands() const {
186	    return reinterpret_cast<const Use *>(this) - NumUserOperands;
187	  }
188	
189	  Use *getIntrusiveOperands() {
190	    return reinterpret_cast<Use *>(this) - NumUserOperands;
191	  }
192	
193	  void setOperandList(Use *NewList) {
194	    assert(HasHungOffUses &&
195	           "Setting operand list only required for hung off uses");
196	    getHungOffOperands() = NewList;
197	  }
198	
199	public:
200	  const Use *getOperandList() const {
201	    return HasHungOffUses ? getHungOffOperands() : getIntrusiveOperands();
202	  }
203	  Use *getOperandList() {
204	    return const_cast<Use *>(static_cast<const User *>(this)->getOperandList());
205	  }
206	
207	  Value *getOperand(unsigned i) const {
208	    assert(i < NumUserOperands && "getOperand() out of range!");
209	    return getOperandList()[i];
210	  }
211	
212	  void setOperand(unsigned i, Value *Val) {
213	    assert(i < NumUserOperands && "setOperand() out of range!");
214	    assert((!isa<Constant>((const Value*)this) ||
215	            isa<GlobalValue>((const Value*)this)) &&
216	           "Cannot mutate a constant with setOperand!");
217	    getOperandList()[i] = Val;
218	  }
219	
220	  const Use &getOperandUse(unsigned i) const {
221	    assert(i < NumUserOperands && "getOperandUse() out of range!");
222	    return getOperandList()[i];
223	  }
224	  Use &getOperandUse(unsigned i) {
225	    assert(i < NumUserOperands && "getOperandUse() out of range!");
226	    return getOperandList()[i];
227	  }
228	
229	  unsigned getNumOperands() const { return NumUserOperands; }
230	
231	  /// Returns the descriptor co-allocated with this User instance.
232	  LLVM_ABI ArrayRef<const uint8_t> getDescriptor() const;
233	
234	  /// Returns the descriptor co-allocated with this User instance.
235	  LLVM_ABI MutableArrayRef<uint8_t> getDescriptor();
236	
237	  /// Subclasses with hung off uses need to manage the operand count
238	  /// themselves.  In these instances, the operand count isn't used to find the
239	  /// OperandList, so there's no issue in having the operand count change.
240	  void setNumHungOffUseOperands(unsigned NumOps) {
241	    assert(HasHungOffUses && "Must have hung off uses to use this method");
242	    assert(NumOps < (1u << NumUserOperandsBits) && "Too many operands");
243	    NumUserOperands = NumOps;
244	  }
245	
246	  /// A droppable user is a user for which uses can be dropped without affecting
247	  /// correctness and should be dropped rather than preventing a transformation
248	  /// from happening.
249	  LLVM_ABI bool isDroppable() const;
250	
251	  // ---------------------------------------------------------------------------
252	  // Operand Iterator interface...
253	  //
254	  using op_iterator = Use*;
255	  using const_op_iterator = const Use*;
256	  using op_range = iterator_range<op_iterator>;
257	  using const_op_range = iterator_range<const_op_iterator>;
258	
259	  op_iterator       op_begin()       { return getOperandList(); }
260	  const_op_iterator op_begin() const { return getOperandList(); }
261	  op_iterator       op_end()         {
262	    return getOperandList() + NumUserOperands;
263	  }
264	  const_op_iterator op_end()   const {
265	    return getOperandList() + NumUserOperands;
266	  }
267	  op_range operands() {
268	    return op_range(op_begin(), op_end());
269	  }
270	  const_op_range operands() const {
271	    return const_op_range(op_begin(), op_end());
272	  }
273	
274	  /// Iterator for directly iterating over the operand Values.
275	  struct value_op_iterator
276	      : iterator_adaptor_base<value_op_iterator, op_iterator,
277	                              std::random_access_iterator_tag, Value *,
278	                              ptrdiff_t, Value *, Value *> {
279	    explicit value_op_iterator(Use *U = nullptr) : iterator_adaptor_base(U) {}
280	
281	    Value *operator*() const { return *I; }
282	    Value *operator->() const { return operator*(); }
283	  };
